    @EventHandler( payloadType=UpdateInterviewEvent.class )
    public void handle( UpdateInterviewEvent event) {
    	LOGGER.info("handling UpdateInterviewEvent - " + event );
    	
	    Interview entity = new Interview();
            entity.setInterviewId( event.getInterviewId() );
            entity.setInterviewDate( event.getInterviewDate() );
            entity.setFeedback( event.getFeedback() );
            entity.setRequisition( event.getRequisition() );
            entity.setCandidate( event.getCandidate() );
            entity.setInterviewers( event.getInterviewers() );
            entity.setStage( event.getStage() );
            entity.setResult( event.getResult() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindInterview( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllInterview( entity );        
    }
    
