    /**
     * Method to retrieve the Interview via an InterviewPrimaryKey.
     * @param 	id Long
     * @return 	Interview
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Interview handle( FindInterviewQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getInterviewId() );
    }
    
    /**
     * Method to retrieve a collection of all Interviews
     *
     * @param	query	FindAllInterviewQuery 
     * @return 	List<Interview> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Interview> handle( FindAllInterviewQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindInterview,
 * but only if the id matches
 *
 * @param		entity	Interview
 */
	protected void emitFindInterview( Interview entity ) {
		LOGGER.info("handling emitFindInterview" );
		
	    queryUpdateEmitter.emit(FindInterviewQuery.class,
	                            query -> query.getFilter().getInterviewId().equals(entity.getInterviewId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllInterview
	 * 
	 * @param		entity	Interview
	 */
	protected void emitFindAllInterview( Interview entity ) {
		LOGGER.info("handling emitFindAllInterview" );
		
	    queryUpdateEmitter.emit(FindAllInterviewQuery.class,
	                            query -> true,
	                            entity);
	}

